import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 size
)
{
    .reg .u64 %rd<10>;
    .reg .u32 %r<10>;
    .reg .f32 %f<10>;
    .reg .pred %p1;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [size];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;

    setp.ge.u32 %p1, %r5, %r1;
    @%p1 bra DONE;

    mul.wide.u32 %rd3, %r5, 4;
    add.s64 %rd4, %rd1, %rd3;
    add.s64 %rd5, %rd2, %rd3;

    ld.global.f32 %f1, [%rd4];
    tanh.approx.f32 %f2, %f1;
    st.global.f32 [%rd5], %f2;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input tensor must be on CUDA device"
        x_contig = x.contiguous()
        out = torch.empty_like(x_contig)

        total_elements = x_contig.numel()

        module = _get_ptx_module()

        block_x = 256
        grid_x = (total_elements + block_x - 1) // block_x

        module.launch(
            "tanh_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x_contig, out, i32(total_elements)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out.view(x.shape)

